-- ---------- Publicar el B1 de Inglés y Español (sigue siendo Premium) ----------
UPDATE ruta_niveles n INNER JOIN idiomas i ON i.id = n.idioma_id SET n.publicado = 1 WHERE n.codigo = 'B1' AND i.codigo IN ('EN', 'ES');

