INSERT IGNORE INTO medallas (codigo, nombre, descripcion, icono, categoria, condicion, meta, idioma_id, nivel, color, orden) SELECT CONCAT('b1_', LOWER(i.codigo)), CONCAT('B1 de ', CASE i.codigo WHEN 'EN' THEN 'inglés' ELSE 'español' END), CONCAT('Terminaste el nivel B1 de ', CASE i.codigo WHEN 'EN' THEN 'inglés' ELSE 'español' END), 'fa-flag-checkered', 'ruta', 'ruta_nivel', 1, i.id, 'B1', 'azul', CASE i.codigo WHEN 'EN' THEN 116 ELSE 117 END FROM idiomas i WHERE i.codigo IN ('EN', 'ES');
